/** Snapshot-backed guide-draft wizard. The session only remembers a choice, never rules. */
function gnre_guide_draft_store_flash(string $company,string $route,int $guideId,int $itemId,string $action,string $message,bool $error):string {
    $key=$route.':'.$guideId.':'.$itemId;$_SESSION[GNRE_SESSION]['guide_draft_flash'][$company][$key]=['message'=>$message,'error'=>$error,'action'=>$action,'route'=>$route,'guide_id'=>$guideId,'item_id'=>$itemId];return $key;
}
function gnre_guide_draft_redirect(string $url, string $message, bool $error=false, array $scope=[]): void {
    $company=(string)($GLOBALS['gnre_guide_draft_company']??'');$guideId=(int)($scope['guide_id']??($_POST['guide_id']??0));$itemId=(int)($scope['item_id']??($_POST['item_id']??0));$route=(string)($scope['route']??($guideId?'guide':'new'));gnre_guide_draft_store_flash($company,$route,$guideId,$itemId,(string)($_POST['action']??''),$message,$error);header('Location: '.$url, true, 303);exit;
}
function gnre_guide_draft_take_flash(array $context,string $route,int $guideId=0,int $itemId=0,array $allowedActions=[]):?array {
    $company=(string)$context['company_id'];$key=$route.':'.$guideId.':'.$itemId;$flash=$_SESSION[GNRE_SESSION]['guide_draft_flash'][$company][$key]??null;unset($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company][$key]);if(empty($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company]))unset($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company]);if(!is_array($flash)||($allowedActions&&!in_array((string)($flash['action']??''),$allowedActions,true)))return null;return $flash;
}
/** Entering creation dismisses only guide-scoped notices; preserved guide POSTs remain untouched. */
function gnre_guide_draft_enter_new(array $context):void {
    $company=(string)$context['company_id'];foreach((array)($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company]??[]) as $key=>$flash)if(is_array($flash)&&(($flash['route']??'')==='guide'||($flash['action']??'')==='guide_draft_save_item'))unset($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company][$key]);
    /* Legacy flat flash had no company/route key. Only discard its unmistakable item-edit message. */
    $legacy=$_SESSION[GNRE_SESSION]['guide_draft_flash']??null;if(is_array($legacy)&&isset($legacy['message'])&&preg_match('/\bitem\b/i',(string)$legacy['message']))unset($_SESSION[GNRE_SESSION]['guide_draft_flash']);
    if(empty($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company]))unset($_SESSION[GNRE_SESSION]['guide_draft_flash'][$company]);
}
function gnre_guide_draft_prepare(mysqli $db,string $sql,string $stage,int $guideId,int $itemId): mysqli_stmt {
    $statement=mysqli_prepare($db,$sql);
    if($statement instanceof mysqli_stmt)return $statement;
    $detail=mysqli_error($db);error_log('GNRE GuideDraft prepare failed stage='.$stage.' guide='.$guideId.' item='.$itemId.' mysql='.$detail);
    throw new RuntimeException('Não foi possível preparar a gravação do item. Consulte o log técnico.');
}
/** Browser messages stay actionable without leaking driver/PHP/SOAP/XML internals. */
function gnre_guide_draft_public_error(Throwable $e,int $guideId,int $itemId,string $action=''): string {
    $message=$e->getMessage();
    error_log('GNRE GuideDraft failure guide='.$guideId.' item='.$itemId.' detail='.$message);
    if($action==='guide_draft_consult'){
        $category=$e instanceof GnreConfigUfConsultException?$e->publicCategory():GnreConfigUfConsultException::INCONCLUSIVE;
        if($category===GnreConfigUfConsultException::CERTIFICATE_UNAVAILABLE)return 'O certificado digital da empresa não está disponível para acessar o Portal GNRE. Solicite a regularização e tente novamente. Nenhuma guia foi criada.';
        if($category===GnreConfigUfConsultException::PORTAL_ACCESS_DENIED)return 'O Portal GNRE não autorizou esta empresa a consultar as configurações da UF. Verifique a habilitação para uso do Web Service no Portal e tente novamente. Nenhuma guia foi criada.';
        return 'Não foi possível acessar o Portal GNRE neste momento. Verifique o certificado digital e a habilitação da empresa no Portal antes de tentar novamente. Nenhuma guia foi criada.';
    }
    if($action==='guide_draft_create')return 'Não foi possível criar o rascunho agora. Revise a configuração e tente novamente.';
    if(preg_match('/(?:mysql|mysqli|sql|database|php|soap|xml|xsd|tls|exception|warning|notice|stack)/i',$message))return 'Não foi possível gravar o item agora. Seus dados foram mantidos para correção.';
    return $message;
}
/** GNRE009 is read once for a new draft; the linked GNRE007 remains authoritative afterwards. */
function gnre_guide_draft_intended_environment(array $context): string {
    $db=gnre_db();
    try { $environment=(new GnreEnvironmentPreference())->read($db,(int)$context['company_id']); }
    finally { mysqli_close($db); }
    return GnreEnvironmentResolver::assertOperationalAllowed($environment);
}
